<?php
declare(strict_types=1);
const INC_META=['namen','original_nummern','externe_ids','notizen','quellen_verweise','berufe','ausbildungen','wohnsitze','migrationen','religionsgeschichte','militaerdienst','weitere_ereignisse','auszeichnungen','vereinsmitgliedschaften','benutzerdefinierte_felder'];
function incNamespace(mixed $value): string {if(!is_string($value)||!preg_match('/^[a-z0-9][a-z0-9_-]{1,79}$/D',$value))fail(422,'Stabile Datenquellen-Kennung erforderlich, z. B. kreutzwiesner. Bei späteren Updates gleich lassen.');return $value;}
function incTarget(string $ns,string $id): string{return 'imp_'.hash('sha256',$ns."\0".$id);}
function incAlias(string $ns,string $id): string{return 'import_alias_'.hash('sha256',$ns."\0".$id);}
function incKey(string $s): string{$s=mb_strtolower($s);$s=strtr($s,['ä'=>'a','ö'=>'o','ü'=>'u','ß'=>'ss','é'=>'e','è'=>'e','á'=>'a','č'=>'c','š'=>'s']);return trim(preg_replace('/[^\p{L}\p{N}]+/u',' ',$s));}
function incNames(array $p): array{$out=[$p['anzeigename']??''];foreach($p['namen']['namensvarianten']??[] as $v)if(is_array($v)&&is_string($v['name']??null))$out[]=$v['name'];$first=$p['namen']['vornamen']??'';if(is_array($first))$first=implode(' ',array_filter($first,'is_string'));if(is_string($first)&&$first!=='')foreach(['familienname','geburtsname'] as $k)if(is_string($p['namen'][$k]??null))$out[]=$first.' '.$p['namen'][$k];return array_values(array_unique(array_filter(array_map('incKey',$out))));}
function incKnown(array $p): bool{$n=incKey($p['anzeigename']??'');return mb_strlen($n)>2&&!str_contains($p['anzeigename']??'','?')&&!preg_match('/^(unbekannt(?:e[rsnm]?)?|unknown|n n|totgeburt)( |$)/u',$n);}
function incPossible(array $p,array $q): bool{if(!incKnown($p)||!incKnown($q))return false;if(array_intersect(incNames($p),incNames($q)))return true;$firstP=explode(' ',incKey($p['anzeigename']))[0];$firstQ=explode(' ',incKey($q['anzeigename']))[0];$lastP=array_filter([incKey((string)($p['namen']['familienname']??'')),incKey((string)($p['namen']['geburtsname']??''))]);$lastQ=array_filter([incKey((string)($q['namen']['familienname']??'')),incKey((string)($q['namen']['geburtsname']??''))]);if(array_intersect($lastP,$lastQ)&&($firstP===$firstQ||strlen($firstP)>3&&strlen($firstQ)>3&&levenshtein($firstP,$firstQ)<=2))return true;$b=gp($p,'geburt.datum.iso');$d=gp($q,'geburt.datum.iso');if(is_string($b)&&strlen($b)===10&&$b===$d)return true;return false;}
function incAliases(PDO $db,string $ns): array{$out=[];foreach(query($db,"SELECT data FROM ah_settings WHERE id LIKE 'import_alias_%'")->fetchAll() as $row){$x=decode($row['data']);if(($x['namespace']??'')===$ns)$out[$x['source_id']]=$x['target'];}return $out;}
function incMatch(array $p,array $existing,array $aliases,string $ns,array $batch): array{
 $byId=[];foreach($existing as $r)$byId[$r['id']]=$r;$stable=$aliases[$p['id']]??(isset($byId[$p['id']])?$p['id']:(isset($byId[incTarget($ns,$p['id'])])?incTarget($ns,$p['id']):null));
 if($stable&&!isset($byId[$stable]))fail(409,'Gespeicherte Quellzuordnung verweist auf eine fehlende Person. Admin muss die Zuordnung prüfen.');
 $candidates=[];foreach($existing as $r)if(incPossible($p,$r['data']))$candidates[]=['id'=>$r['id'],'name'=>$r['data']['anzeigename'],'birth'=>gp($r['data'],'geburt.datum.iso')];
 $incoming=[];foreach($batch as $other)if($other['id']!==$p['id']&&incPossible($p,$other))$incoming[]=$other['id'];
 $exact=array_values(array_filter($candidates,fn($r)=>is_string(gp($p,'geburt.datum.iso'))&&strlen(gp($p,'geburt.datum.iso'))===10&&$r['birth']===gp($p,'geburt.datum.iso')&&incKey($r['name'])===incKey($p['anzeigename'])&&!gp($p,'geburt.datum.konflikt')&&!gp($byId[$r['id']]['data'],'geburt.datum.konflikt')));
 $conflict=false;if($stable){$old=$byId[$stable]['data'];$birth=gp($p,'geburt.datum.iso');$conflict=incKnown($p)&&incKnown($old)&&!array_intersect(incNames($p),incNames($old))&&(!is_string($birth)||strlen($birth)!==10||$birth!==gp($old,'geburt.datum.iso'));}
 $target=$stable??(count($exact)===1?$exact[0]['id']:null);
 return ['source_id'=>$p['id'],'target'=>$target,'stable'=>(bool)$stable,'identity_conflict'=>$conflict,'candidates'=>$candidates,'incoming_duplicates'=>$incoming,'can_create'=>!$target&&!$candidates&&!$incoming&&incKnown($p),'reason'=>$conflict?'Quell-ID mit abweichender Identität: überspringen oder Datenquelle/IDs korrigieren':($stable?'Gespeicherte Identität / Quellzuordnung':($target?'Eindeutiger Name und vollständiges Geburtsdatum':($incoming?'Mögliche Dublette innerhalb der Datei':($candidates?'Mögliche vorhandene Person – zuordnen oder überspringen':(!incKnown($p)?'Namenslose Person kann nicht automatisch neu angelegt werden':'Neuzugang muss ausdrücklich bestätigt werden')))))];
}
function incAnalysis(PDO $db,array $data,string $ns,array $mapping=[]): array{$existing=records($db,'person');$aliases=incAliases($db,$ns);$batch=array_values(array_filter($data['personen'],fn($p)=>($mapping[$p['id']]??'')!=='skip'));$out=[];foreach($data['personen'] as $p)$out[]=incMatch($p,$existing,$aliases,$ns,$batch);return $out;}
function incMerge(mixed $old,mixed $new,array &$warnings,string $label): mixed{
 if($new===null||$new===''||$new===[]||in_array($new,['unbekannt','ungeklaert'],true))return $old;
 if($old===null||$old===''||$old===[]||in_array($old,['unbekannt','ungeklaert'],true))return $new;
 if($old===$new)return $old;
 if(is_array($old)&&is_array($new)){if(array_is_list($old)&&array_is_list($new)){$keys=[];$out=[];foreach(array_merge($old,$new) as $v){$k=jencode($v);if(!isset($keys[$k])){$out[]=$v;$keys[$k]=true;}}return $out;}$out=$old;foreach($new as $k=>$v)$out[$k]=incMerge($old[$k]??null,$v,$warnings,$label.'.'.$k);return $out;}
 $warnings[]=$label.': abweichender Wert bleibt unverändert im Bestand.';return $old;
}
function incrementalPlan(PDO $db,array $data,array $mapping,string $batch,string $ns): array{
 $ns=incNamespace($ns);$out=['incremental'=>true,'namespace'=>$ns,'new'=>[],'patches'=>[],'families'=>[],'family_patches'=>[],'relationships'=>[],'warnings'=>$data['hinweise'],'person_ids'=>[],'source_map'=>[]];$map=[];$used=[];$analysis=incAnalysis($db,$data,$ns,$mapping);$checks=array_column($analysis,null,'source_id');
 foreach($data['personen'] as $p){$id=$p['id'];$m=$checks[$id];$choice=$mapping[$id]??($m['target']??'');if(!is_string($choice))fail(422,'Ungültige Personenzuordnung.');if($choice==='skip'){$map[$id]=null;continue;}if($m['identity_conflict'])fail(409,'Quell-ID kollidiert mit einer anderen Identität: '.$p['anzeigename'].'. Überspringen oder Quellenkennung/IDs korrigieren.');
  if($choice==='new')fail(422,'Neuzugänge müssen ausdrücklich als new_confirmed bestätigt werden.');
  if($m['stable']&&$choice!==$m['target']&&$choice!=='new_confirmed')fail(409,'Gespeicherte Quellidentität darf nicht auf eine andere Person umgebogen werden: '.$p['anzeigename']);
  if($choice==='new_confirmed'){
   // An identical concurrently approved import now has this deterministic identity.
   if($m['stable'])$choice=$m['target'];else{if(!$m['can_create'])fail(409,'Neuanlage wegen möglicher Dublette gesperrt: '.$p['anzeigename'].'. Zugeordneten Datensatz wählen oder überspringen.');$target=incTarget($ns,$id);$per=$p;$per['id']=$target;$out['new'][]=$per;}
  }
  if($choice!=='new_confirmed'){
   if(!$choice)fail(422,'Person noch nicht zugeordnet: '.$p['anzeigename']);$target=identifier($choice);$r=getRecord($db,$target);if(!$r||$r['kind']!=='person')fail(422,'Zugeordnete Person fehlt.');$changes=[];$extra=[];$after=$r['data'];
   foreach(IMPORT_FIELDS as $key){if($key==='anzeigename'){if(!incKnown($r['data'])&&incKnown($p)){$changes[$key]=$p['anzeigename'];$after[$key]=$p['anzeigename'];}continue;}$value=gp($p,$key);$old=gp($r['data'],$key);if($value===null||$value===''||in_array($value,['unbekannt','ungeklaert'],true))continue;if($old===null||$old===''||in_array($old,['unbekannt','ungeklaert'],true)){$changes[$key]=$value;sp($after,$key,$value);}elseif($old!==$value)$out['warnings'][]=$p['anzeigename'].': Konflikt bei '.$key.' – vorhandener Wert bleibt erhalten.';}
   foreach(INC_META as $key)if(isset($p[$key])){$merged=incMerge($r['data'][$key]??null,$p[$key],$out['warnings'],$p['anzeigename'].'.'.$key);if($merged!==($r['data'][$key]??null)){$extra[$key]=$merged;$after[$key]=$merged;}}
   chronology($after);$out['patches'][]=['id'=>$target,'base_version'=>$r['version'],'changes'=>$changes,'extra'=>$extra,'name'=>$r['data']['anzeigename']];
  }
  if(isset($used[$target]))fail(409,'Mehrere Quellpersonen würden dieselbe Person belegen. Dublette innerhalb der Datei bereinigen oder einen Eintrag überspringen.');$used[$target]=true;$map[$id]=$target;
 }
 $out['source_map']=array_filter($map,fn($v)=>$v!==null);$out['person_ids']=array_values($out['source_map']);if(!$out['person_ids'])fail(422,'Keine Personen ausgewählt.');
 $edges=[];foreach(records($db,'relationship') as $row){$r=$row['data'];$pair=[$r['von_person_id'],$r['zu_person_id']];if($r['typ']==='partner')sort($pair);$edges[$r['typ'].':'.jencode($pair)]=$r;}
 $families=records($db,'family');foreach($families as $r){$pair=$r['data']['partner_person_ids']??[];if(count($pair)===2){sort($pair);$edges['partner:'.jencode($pair)]=$r['data'];}}
 foreach($data['beziehungen'] as $r){$a=$map[$r['von_person_id']]??null;$b=$map[$r['zu_person_id']]??null;if(!$a||!$b)continue;$r['von_person_id']=$a;$r['zu_person_id']=$b;validate('relationship',$r);$pair=[$a,$b];if($r['typ']==='partner')sort($pair);$key=$r['typ'].':'.jencode($pair);if(isset($edges[$key])){if($r['typ']==='eltern_kind'&&($r['elternschaft_typ']??'ungeklaert')!=='ungeklaert'&&($edges[$key]['elternschaft_typ']??'ungeklaert')!==$r['elternschaft_typ'])$out['warnings'][]='Abweichende Elternschaft bei bestehender Verbindung: separat prüfen; keine zweite Verbindung angelegt.';continue;}$edges[$key]=$r;$r['id']='rel_'.hash('sha256',$key);$out['relationships'][]=$r;}
 $planned=[];
 foreach($data['familien'] as $f){$partners=array_values(array_filter(array_map(fn($id)=>$map[$id]??null,$f['partner_person_ids'])));$children=array_values(array_filter(array_map(fn($id)=>$map[$id]??null,$f['kinder_person_ids'])));if(!$partners)continue;sort($partners);$key=jencode($partners);$matches=array_values(array_filter($families,function($row)use($partners){$ids=$row['data']['partner_person_ids']??[];sort($ids);return $ids===$partners;}));
  if(count($matches)>1){$date=gp($f,'hochzeit.datum.iso');$exact=array_values(array_filter($matches,fn($row)=>$date&&gp($row['data'],'hochzeit.datum.iso')===$date));if(count($exact)!==1)fail(409,'Mehrere vorhandene Familiengruppen für dieselben Partner. Vor Update eindeutig bereinigen.');$matches=$exact;}
  if(isset($planned[$key])&&gp($planned[$key]['after'],'hochzeit.datum.iso')&&gp($f,'hochzeit.datum.iso')&&gp($planned[$key]['after'],'hochzeit.datum.iso')!==gp($f,'hochzeit.datum.iso'))fail(409,'Verschiedene Hochzeiten derselben Partner bitte eindeutig bereinigen.');
  if($matches){$r=$matches[0];if(gp($r['data'],'hochzeit.datum.iso')&&gp($f,'hochzeit.datum.iso')&&gp($r['data'],'hochzeit.datum.iso')!==gp($f,'hochzeit.datum.iso'))fail(409,'Abweichende Hochzeit derselben Partner: Familienzuordnung vor dem Update klären.');$after=$planned[$key]['after']??$r['data'];$after['kinder_person_ids']=array_values(array_unique(array_merge($after['kinder_person_ids']??[],$children)));$after['hochzeit']=incMerge($after['hochzeit']??null,$f['hochzeit'],$out['warnings'],'Hochzeit der Familie');$planned[$key]=['id'=>$r['id'],'base_version'=>$r['version'],'before'=>$r['data'],'after'=>$after];}
  else{if(!isset($planned[$key]))$planned[$key]=['id'=>'fam_'.hash('sha256',$key),'after'=>['id'=>'fam_'.hash('sha256',$key),'partner_person_ids'=>$partners,'kinder_person_ids'=>[],'hochzeit'=>$f['hochzeit'],'status'=>'freigegebener_import']];$planned[$key]['after']['kinder_person_ids']=array_values(array_unique(array_merge($planned[$key]['after']['kinder_person_ids'],$children)));}
 }
 foreach($planned as $f){if(isset($f['base_version'])){if($f['after']!==$f['before']){unset($f['before']);$out['family_patches'][]=$f;}}else$out['families'][]=$f['after'];}
 $aliases=incAliases($db,$ns);$out['identity_links']=count(array_filter($out['source_map'],fn($target,$source)=>!isset($aliases[$source]),ARRAY_FILTER_USE_BOTH));
 $changed=array_filter($out['patches'],fn($p)=>$p['changes']||$p['extra']);$out['no_changes']=!$out['new']&&!$changed&&!$out['relationships']&&!$out['families']&&!$out['family_patches']&&!$out['identity_links'];$out['warnings']=array_values(array_unique($out['warnings']));return $out;
}
function incRegister(PDO $db,array $plan): void{foreach($plan['source_map'] as $source=>$target){$key=incAlias($plan['namespace'],(string)$source);$old=one($db,'SELECT data FROM ah_settings WHERE id=?',[$key]);if($old&&decode($old['data'])['target']!==$target)fail(409,'Quellidentität zwischenzeitlich anders zugeordnet.');if(!$old)query($db,'INSERT INTO ah_settings VALUES (?,?)',[$key,jencode(['namespace'=>$plan['namespace'],'source_id'=>(string)$source,'target'=>$target])]);}}
